from collections import deque
def comps(grid, eight=False):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 offs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (eight or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    q=deque([(r,c)]);seen.add((r,c)); cs=[]
    while q:
     y,x=q.popleft();cs.append((y,x))
     for dy,dx in offs:
      yy,xx=y+dy,x+dx
      if 0<=yy<h and 0<=xx<w and grid[yy][xx] and (yy,xx) not in seen: seen.add((yy,xx));q.append((yy,xx))
    out.append(cs)
 return out
